def transform(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    h_out, w_out = 2*h, 2*w
    output = [[0] * w_out for _ in range(h_out)]

    # TL: input grid as-is
    for r in range(h):
        for c in range(w):
            output[r][c] = input_grid[r][c]

    # TR: columns as reversed rows
    for r in range(h):
        for c in range(w):
            output[r][w + c] = input_grid[h - 1 - c][r]

    # BL: columns become rows (read top-to-bottom)
    for r in range(h):
        for c in range(w):
            output[h + r][c] = input_grid[c][h - 1 - r]

    # BR: 180° rotation
    for r in range(h):
        for c in range(w):
            output[h + r][w + c] = input_grid[h - 1 - r][w - 1 - c]

    return output

