    h_out, w_out = 2*h, 2*w
    output = [[0] * w_out for _ in range(h_out)]

    # TL: input grid as-is
    for r in range(h):
        for c in range(w):
            output[r][c] = input_grid[r][c]

    # TR: each column becomes a reversed row
    for r in range(h):
